import csv
from collections import defaultdict

############################
# GENERATED BY QWEN3.8-27B #
############################

def sector_of(postcode):
    pc = postcode.strip().replace(" ", "")
    if len(pc) < 5:
        return None
    return pc[:-2]


def normal_of(postcode):
    pc = postcode.strip().replace(" ", "")
    if len(pc) < 5:
        return None
    return pc


def majority(regions):
    """Given {region: count}, return the winning region. Ties broken by
    alphabetical order for determinism."""
    total = sum(regions.values())
    winner = max(sorted(regions), key=lambda r: regions[r])
    return winner, (regions[winner] / total if total else 0)


def main(path):
    sector_counts = defaultdict(lambda: defaultdict(int))  # sector -> region -> count
    unit_counts   = defaultdict(lambda: defaultdict(int))  # unit postcode -> region -> count

    with open(path, newline="") as f:
        for row in csv.DictReader(f):
            pc  = (row.get("pcd7") or "").strip()
            reg = (row.get("rgn25cd")   or "").strip()
            if not pc or not reg:
                continue
            s, u = sector_of(pc), normal_of(pc)
            if s is None or u is None:
                continue
            sector_counts[s][reg] += 1
            unit_counts[u][reg] += 1

    # --- Sector-level map (all sectors, majority-voted) ---
    sector_map = {}
    ambiguous_sectors = set()
    for s, regions in sector_counts.items():
        winner, _pct = majority(regions)
        sector_map[s] = winner
        if len(regions) > 1:
            ambiguous_sectors.add(s)

    # --- Unit-level map (only postcodes inside ambiguous sectors) ---
    unit_map = {}
    for u, regions in unit_counts.items():
        if sector_of(u) in ambiguous_sectors:
            winner, _pct = majority(regions)
            unit_map[u] = winner

    # --- Write both tables (compact keys, tab-separated) ---
    with open("internal/region_mapping/sectors.tsv", "w") as f:
        for s in sorted(sector_map):
            f.write(f"{s}\t{sector_map[s]}\n")

    with open("internal/region_mapping/units.tsv", "w") as f:
        for u in sorted(unit_map):
            f.write(f"{u}\t{unit_map[u]}\n")

    # --- Summary ---
    print(f"Total sectors:              {len(sector_map)}")
    print(f"Ambiguous sectors:          {len(ambiguous_sectors)} "
          f"({len(ambiguous_sectors)/len(sector_map)*100:.1f}%)")
    print(f"Unit postcodes in fallback: {len(unit_map)}")
    print()

    # Show a few of the ambiguous sectors with their splits, for verification.
    print("Sample ambiguous sectors (worst first):")
    ranked = []
    for s in ambiguous_sectors:
        _winner, pct = majority(sector_counts[s])
        ranked.append((pct, s))
    ranked.sort()  # ascending winner% = most even splits first
    for pct, s in ranked[:10]:
        parts = ", ".join(f"{reg}={cnt}"
                          for reg, cnt in sorted(sector_counts[s].items(), key=lambda x: -x[1]))
        print(f"  {s}: {parts}  (winner at {pct*100:.0f}%)")


if __name__ == "__main__":
    import sys
    main(sys.argv[1] if len(sys.argv) > 1 else "ONSPD_MAY_2026_UK.csv")